import { computed, Injectable, signal } from '@angular/core';
import { MUNICIPALITY_INDEX_URL } from '../map/map.config';

const LIMIT = 8;

export const SHORTEST = 2;

export interface Match {
  // LAU code: the final URL segment.
  readonly id: string;
  readonly name: string;
  // NUTS 3 code: the province URL segment.
  readonly province: string;
  readonly provinceName: string;
  // NUTS 2 code: derived from the province code.
  readonly region: string;
}

interface Entry extends Match {
  readonly keys: readonly string[];
}

// Generated by scripts/build-index.mjs.
interface Index {
  readonly municipalities: readonly (readonly [string, string, string, string])[];
}

// Unicode decomposition handles accents across the five languages, including ç and ñ.
function fold(text: string): string {
  return text
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase();
}

// Match bilingual halves and trailing articles (Coruña, A → A Coruña). Only short trailing parts
// count as articles; Portuguese merged parish names also contain commas. Apostrophes take no added
// space (L’Ametlla).
function keysOf(name: string): readonly string[] {
  const keys = new Set<string>([fold(name)]);

  const trailing = /^(.+), (\S{1,4})$/.exec(name);
  if (trailing) {
    const [, rest, article] = trailing;
    keys.add(fold(/['’]$/.test(article) ? article + rest : article + ' ' + rest));
  }

  if (name.includes('/')) for (const half of name.split('/')) keys.add(fold(half.trim()));

  return [...keys];
}

function score(entry: Entry, query: string): number {
  let best = Infinity;

  for (const key of entry.keys) {
    const at = key.indexOf(query);
    if (at < 0) continue;
    if (at === 0) return 0;
    best = Math.min(best, /[\s'’\-(]/.test(key[at - 1]) ? 1 : 2);
  }

  return best;
}

// Unlike the hierarchy services, search needs the complete municipality index because no province
// is known yet.
@Injectable({ providedIn: 'root' })
export class SearchService {
  private readonly entries = signal<readonly Entry[]>([]);

  public readonly failed = signal(false);
  private asked = false;

  public readonly ready = computed(() => this.entries().length > 0);

  // Load on focus so visits that never search do not download the index.
  public load(): void {
    if (this.asked) return;
    this.asked = true;
    this.failed.set(false);

    // Resolve against document.baseURI; the active route may have several segments.
    const url = new URL(MUNICIPALITY_INDEX_URL, document.baseURI).href;

    fetch(url)
      .then((response) => {
        if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
        return response.json() as Promise<Index>;
      })
      .then((index) => {
        this.entries.set(
          index.municipalities.map(([name, id, province, provinceName]) => ({
            id,
            name,
            province,
            provinceName,
            // NUTS is hierarchical: the region code is the first four province-code characters.
            region: province.slice(0, 4),
            keys: keysOf(name),
          })),
        );
      })
      .catch((error: Error) => {
        console.error('[search]', error);
        this.failed.set(true);
        // Forget the failed read: these data are asked for once, so without this the screen has
        // no way back from a passing network failure.
        this.asked = false;
      });
  }

  // Reading the index signal makes computed searches rerun when loading finishes. A linear scan
  // stays below one frame at this catalogue size.
  public matches(query: string): readonly Match[] {
    const wanted = fold(query.trim());
    if (wanted.length < SHORTEST) return [];

    const found: { readonly entry: Entry; readonly rank: number }[] = [];
    for (const entry of this.entries()) {
      const rank = score(entry, wanted);
      if (rank !== Infinity) found.push({ entry, rank });
    }

    // The index is already name-sorted; stable sorting preserves that order for equal ranks.
    found.sort((a, b) => a.rank - b.rank);

    return found.slice(0, LIMIT).map(({ entry }) => entry);
  }
}
